head.script:

scwin.onpageload = function() {
	progressbar1.set(14);
	progressbar2.set(28);
	progressbar3.set(30);
	progressbar4.set(70);
};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('progressbar1_label').innerText == '14%';
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('progressbar2_label').innerText == '28%';
}	
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
